// Agency branding for the flight tracker.
//
// Every agency has its real logo (fetched from Wikimedia Commons /
// en.wikipedia, or the agency's own site for Wakanow) embedded as a
// data URI, plus its brand colour. Emirates keeps the logo Craig
// supplied himself, which lives in ./logo.ts.
//
// The admin picks an agency per flight; the boarding-pass card, the
// status card and the booking PDF all take that agency's logo and
// colours. Emirates is the default, so existing flights are unchanged.

import { EMIRATES_LOGO_DATA_URL } from "./logo";

export type AgencyKind = "airline" | "booking";

export type Agency = {
  id: string;
  name: string;
  group: string;
  kind: AgencyKind;
  /** Brand colour, used for the pass title and rules. */
  primary: string;
  /** Logo as a data URI (SVG preferred; PNG/JPEG where no SVG exists). */
  logo: string;
};

export const DEFAULT_AGENCY_ID = "emirates";

