const GROUP_ORDER = ["Middle East & North Africa", "Europe", "Africa", "Americas", "Asia & Pacific", "Booking sites"];

export const AGENCY_GROUPS: { name: string; agencies: Agency[] }[] =
  GROUP_ORDER.map((name) => ({
    name,
    agencies: AGENCIES.filter((a) => a.group === name),
  }));

/** Agency for an id, or Emirates when the id is unknown/missing. */
export function getAgency(id: unknown): Agency {
  if (typeof id === "string") {
    const found = AGENCIES.find((a) => a.id === id);
    if (found) return found;
  }
  return AGENCIES[0];
}

/** Keep only known agency ids; anything else falls back to Emirates. */
export function normalizeAgencyId(id: unknown): string {
  return getAgency(id).id;
}

/** Darken a #rrggbb colour by a factor (0-1) for gradients. */
export function darkenHex(hex: string, factor = 0.55): string {
  const m = /^#([0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return hex;
  const n = parseInt(m[1], 16);
  const r = Math.round(((n >> 16) & 255) * factor);
  const g = Math.round(((n >> 8) & 255) * factor);
  const b = Math.round((n & 255) * factor);
  return `#${((r << 16) | (g << 8) | b).toString(16).padStart(6, "0")}`;
}

/** Aspect ratio (width / height) of an SVG logo data URI, or null. */
function svgAspect(logo: string): number | null {
  try {
    const raw = decodeURIComponent(logo.split(",", 2)[1] ?? "");
    const vb = /viewBox\s*=\s*"[^"]*\s([\d.]+)\s+([\d.]+)"/.exec(raw);
    if (vb) {
      const w = Number(vb[1]);
      const h = Number(vb[2]);
      if (w > 0 && h > 0) return w / h;
    }
    const w = /<svg[^>]*\bwidth\s*=\s*"([\d.]+)"/.exec(raw);
    const h = /<svg[^>]*\bheight\s*=\s*"([\d.]+)"/.exec(raw);
    if (w && h) {
      const ww = Number(w[1]);
      const hh = Number(h[1]);
      if (ww > 0 && hh > 0) return ww / hh;
    }
  } catch {}
  return null;
}

/**
 * Rasterize a logo data URI to a PNG data URL for jsPDF (which cannot
 * draw SVGs). Raster logos pass through unchanged. Returns null when
 * the logo cannot be drawn.
 */
export async function logoToPngDataUrl(logo: string, width = 400): Promise<string | null> {
  if (!logo.startsWith("data:image/svg+xml")) return logo;
  try {
    const aspect =
      svgAspect(logo) ??
      (await new Promise<number>((resolve) => {
        const probe = new Image();
        probe.onload = () =>
          resolve(
            probe.naturalWidth > 0 && probe.naturalHeight > 0
              ? probe.naturalWidth / probe.naturalHeight
              : 4,
          );
        probe.onerror = () => resolve(4);
        probe.src = logo;
      }));
    const img = new Image();
    await new Promise<void>((resolve, reject) => {
      img.onload = () => resolve();
      img.onerror = () => reject(new Error("logo load failed"));
      img.src = logo;
    });
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = Math.max(1, Math.round(width / aspect));
    const ctx = canvas.getContext("2d");
    if (!ctx) return null;
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL("image/png");
  } catch {
    return null;
  }
}
